/**
 * Tenancy-guard route exemptions — the documented allowlist for invariant (A).
 *
 * Maintained BY HAND. Each entry is keyed `route::table` and covers exactly ONE
 * (route, table) pair that statically "touches" a FORCEd tenant table (per the
 * coarse word-match in scripts/tenancy-route-audit.mjs) yet is NOT GUC-wrapped —
 * and is exempt by design for the stated reason. The reason must be specific to
 * the pair and grounded in the route's actual code; shared machine-generated
 * sentences are how a real /api/receiving-tasks leak once hid behind a
 * "no-db-false-positive" note. A bare route-only key is still honoured by the
 * guard as a DEPRECATED legacy fallback but blanket-exempts every table the
 * route touches — never add one.
 *
 * Every entry carries `addedAt` (YYYY-MM-DD): the date its reason was verified
 * against the code. The guard HARD-FAILS on any entry missing it, so an
 * exemption can never outlive its last honest review. When a route's tenancy
 * behavior changes, re-verify each of its entries and bump addedAt.
 *
 * Categories:
 *   preauth-identity      /api/auth/* identity/session lookup before a tenant
 *                         context exists (cross-org by necessity; cannot be GUC-scoped).
 *   cross-org-by-design   integration/sync/webhook/cron that legitimately spans orgs
 *                         on the owner pool (org resolved from payload or per-org sweep).
 *   no-db-false-positive  the route runs NO query on the flagged table; the word
 *                         matched an import/type/string/variable.
 *   helper-safe-delegation  tenant-table work is delegated to a GUC-aware src/lib/**
 *                         helper threaded ctx.organizationId; pool (if any) only for
 *                         ctx-stamped recordAudit / api-idempotency.
 *   owner-pool-admin      privileged admin path that must run on the owner pool.
 *
 * RATCHET: a NEW (route, table) pair that violates and is neither GUC-wrapped,
 * exempted here, nor baselined FAILS the guard — add an entry only with an
 * honest, code-verified reason, or GUC-wrap the route instead.
 */

export type ExemptionCategory =
  | 'preauth-identity'
  | 'cross-org-by-design'
  | 'no-db-false-positive'
  | 'helper-safe-delegation'
  | 'owner-pool-admin';

export type RouteTenancyExemption = {
  /** why this ONE (route, table) pair is org-safe by design — specific, code-grounded */
  reason: string;
  category: ExemptionCategory;
  /** date (YYYY-MM-DD) this entry's reason was last verified against the code */
  addedAt: string;
};

